package bucket

import "time"

type Bucket struct {
	Tokens, Capacity, RefillPerSec float64
	Last time.Time
}

func (b *Bucket) Allow(now time.Time) bool {
	b.Tokens = min(b.Capacity, b.Tokens+now.Sub(b.Last).Seconds()*b.RefillPerSec)
	b.Last = now
	if b.Tokens < 1 { return false }
	b.Tokens--
	return true
}

