package bucket

import ("testing"; "time")

func TestBurstThenRefill(t *testing.T) {
	now := time.Now()
	b := &Bucket{Tokens: 2, Capacity: 2, RefillPerSec: 1, Last: now}
	if !b.Allow(now) || !b.Allow(now) || b.Allow(now) { t.Fatal("burst of 2 expected") }
	if !b.Allow(now.Add(time.Second)) { t.Fatal("refill expected") }
}

