package window

import "time"

type Window struct {
	Size time.Duration
	Limit int
	prev, curr int
	start time.Time
}

func (w *Window) Count(now time.Time) float64 {
	elapsed := now.Sub(w.start).Seconds() / w.Size.Seconds()
	return float64(w.prev)*(1-elapsed) + float64(w.curr)
}

files.src/window/allow.go:
package window

import "time"

func (w *Window) Allow(now time.Time) bool {
	if now.Sub(w.start) >= w.Size {
		w.prev, w.curr, w.start = w.curr, 0, now.Truncate(w.Size)
	}
	if w.Count(now) >= float64(w.Limit) { return false }
	w.curr++
	return true
}

