package policycache

import "sync"

type Policy struct{ Capacity, RefillPerSec float64 }

type Cache struct {
	mu sync.RWMutex
	m  map[string]Policy
}

func (c *Cache) Get(key string) (Policy, bool) {
	c.mu.RLock(); defer c.mu.RUnlock()
	p, ok := c.m[key]
	return p, ok
}

files.src/policycache/load.go:
package policycache

func (c *Cache) Load(key string, fetch func(string) (Policy, error)) (Policy, error) {
	if p, ok := c.Get(key); ok { return p, nil }
	p, err := fetch(key)
	if err != nil { return Policy{}, err }
	c.mu.Lock(); c.m[key] = p; c.mu.Unlock()
	return p, nil
}

